<template><div class="project-list-page"><div class="list-view-toolbar"><div class="list-title-block"><div><h1>样件</h1><p class="list-caption">样件按批次管理，左右件默认成组申请和确认</p></div><el-button type="primary" :icon="Plus" @click="ElMessage.info('样件批次创建入口已预留')">新建样件批次</el-button></div><div class="search-control"><el-icon><Search /></el-icon><el-input v-model="keyword" placeholder="搜索批次、项目或报价组" clearable /></div><div class="filter-controls"><el-select v-model="status" placeholder="状态" clearable><el-option v-for="item in ['检验中','客户已接收','客户确认','需整改']" :key="item" :label="item" :value="item" /></el-select></div></div><div class="table-meta"><span>{{ filtered.length }} 个样件批次</span><span>OTS属于量产模具记录，不在此处单独建一级流程</span></div><el-table :data="filtered" stripe><el-table-column prop="id" label="批次号" width="145" /><el-table-column prop="project" label="项目" width="135" /><el-table-column prop="quoteGroup" label="报价组" width="145" /><el-table-column prop="purpose" label="样件用途" min-width="150" /><el-table-column prop="method" label="生产方式" min-width="170" /><el-table-column prop="pair" label="关联" width="120" /><el-table-column prop="qty" label="数量" width="80" /><el-table-column prop="planned" label="计划完成" width="120" /><el-table-column label="状态" width="120"><template #default="{ row }"><el-tag size="small" :type="row.status === '客户已接收' ? 'success' : 'warning'">{{ row.status }}</el-tag></template></el-table-column></el-table></div></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { Plus, Search } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { samples } from './data'
const keyword = ref(''); const status = ref(''); const filtered = computed(() => samples.filter(row => { const text = `${row.id} ${row.project} ${row.quoteGroup} ${row.purpose}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!status.value || row.status === status.value) }))
</script>
<style scoped>.project-list-page{min-width:0;padding:18px 0 30px;color:var(--zephyr-ink)}.project-list-page h1{margin:0;color:var(--zephyr-ink);font-size:19px}.list-caption{margin:5px 0 0;color:var(--zephyr-muted);font-size:11px}</style>
